---

### ✅ Example: Graphing a Function and Its Derivative in p5.js

We'll use the function:

$$
f(x) = x^2
$$

and its derivative:

$$
f'(x) = 2x
$$

We'll plot both on the same graph.

---

### 📜 Code: `derivativeExample.js`

```javascript
let xScale = 10; // scale factor for x-axis
let yScale = -10; // scale factor for y-axis (negative to flip the graph)

function setup() {
  createCanvas(600, 400);
  noFill();
  stroke(255);
  strokeWeight(2);
}

function draw() {
  background(40);

  // Draw axes
  stroke(150);
  strokeWeight(1);
  line(50, height - 50, width - 50, height - 50); // x-axis
  line(50, height - 50, 50, 50); // y-axis

  // Draw the function f(x) = x^2
  stroke(255, 0, 0);
  strokeWeight(2);
  beginShape();
  for (let x = 50; x < width - 50; x += 5) {
    let fx = map(x, 50, width - 50, -5, 5);
    let y = height - 50 - fx * yScale;
    vertex(x, y);
  }
  endShape();

  // Draw the derivative f'(x) = 2x
  stroke(0, 255, 0);
  strokeWeight(2);
  beginShape();
  for (let x = 50; x < width - 50; x += 5) {
    let fx = map(x, 50, width - 50, -5, 5);
    let y = height - 50 - 2 * fx * yScale;
    vertex(x, y);
  }
  endShape();

  // Optional: Show a point and its slope
  let x = 150;
  let fx = map(x, 50, width - 50, -5, 5);
  let y = height - 50 - fx * yScale;
  let fPrimeX = 2 * fx;

  // Draw the point on the function
  fill(255, 0, 0);
  noStroke();
  ellipse(x, y, 8, 8);

  // Draw the tangent line at that point
  let x2 = x + 20;
  let fx2 = map(x2, 50, width - 50, -5, 5);
  let y2 = height - 50 - (fx2) * yScale;
  stroke(255, 0, 0);
  strokeWeight(1);
  line(x, y, x2, y2);
}
```

---

### 📌 How It Works

- The function `f(x) = x^2` is plotted in red.
- The derivative `f'(x) = 2x` is plotted in green.
- A point is shown on the function and a line representing the slope (tangent) at that point is drawn.
- The x and y scales are mapped to fit the canvas.

