  const makeCall = async () => {
    const call = await PhoneCall.call({
      number: '1234567890', // Replace with the phone number
      android: {
        useMobileData: true, // Whether to use mobile data (Android only)
      },
      ios: {
        useMobileData: true, // Whether to use mobile data (iOS only)
      },
