### ✅ **Unity Script: `CreateMesh.cs`**

```csharp
using UnityEngine;

public class CreateMesh : MonoBehaviour
{
    void Start()
    {
        // Ensure the GameObject has MeshFilter and MeshRenderer
        MeshFilter meshFilter = GetComponent<MeshFilter>();
        MeshRenderer meshRenderer = GetComponent<MeshRenderer>();

        if (meshFilter == null)
        {
            meshFilter = gameObject.AddComponent<MeshFilter>();
        }

        if (meshRenderer == null)
        {
            meshRenderer = gameObject.AddComponent<MeshRenderer>();
        }

        // Create a new mesh
        Mesh mesh = new Mesh();
        meshFilter.mesh = mesh;

        // Define vertices for a simple quad (square in the XZ plane)
        Vector3[] vertices = new Vector3[]
        {
            new Vector3(0, 0, 0),
            new Vector3(1, 0, 0),
            new Vector3(1, 0, 1),
            new Vector3(0, 0, 1)
        };

        // Define triangles to form the quad
        int[] triangles = new int[]
        {
            0, 1, 2,
            0, 2, 3
        };

        // Define UVs for texture mapping
        float[] uvs = new float[]
        {
            0, 0,
            1, 0,
            1, 1,
            0, 1
        };

        // Define normals for lighting
        Vector3[] normals = new Vector3[]
        {
            Vector3.up,
            Vector3.up,
            Vector3.up,
            Vector3.up
        };

        // Assign the mesh data
        mesh.vertices = vertices;
        mesh.triangles = triangles;
        mesh.uv = uvs;
        mesh.normals = normals;

        // Recalculate normals (optional, but recommended for lighting)
        mesh.RecalculateNormals();

        // Set the bounds of the mesh
        mesh.bounds = new Bounds(new Vector3(0.5f, 0, 0.5f), new Vector3(1, 0, 1));

        // Create and assign a material
        Material material = new Material(Shader.Find("Standard"));
        material.color = Color.red;

        meshRenderer.material = material;
    }
}
```

